ALTER TABLE public.exercises
  ADD COLUMN IF NOT EXISTS focus_scores jsonb NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS complexity integer,
  ADD COLUMN IF NOT EXISTS fatigue_cost integer,
  ADD COLUMN IF NOT EXISTS spinal_load integer,
  ADD COLUMN IF NOT EXISTS rep_min integer,
  ADD COLUMN IF NOT EXISTS rep_max integer,
  ADD COLUMN IF NOT EXISTS lengthened_bias boolean,
  ADD COLUMN IF NOT EXISTS unilateral boolean,
  ADD COLUMN IF NOT EXISTS impact text,
  ADD COLUMN IF NOT EXISTS leg_interference boolean,
  ADD COLUMN IF NOT EXISTS joint_stress text[],
  ADD COLUMN IF NOT EXISTS setup_cost integer,
  ADD COLUMN IF NOT EXISTS explosive boolean;

UPDATE public.exercises e SET
  focus_scores = v.focus_scores,
  complexity = v.complexity,
  fatigue_cost = v.fatigue_cost,
  spinal_load = v.spinal_load,
  rep_min = v.rep_min,
  rep_max = v.rep_max,
  lengthened_bias = v.lengthened_bias,
  unilateral = v.unilateral,
  impact = v.impact,
